bool check(int x){
	memset(c,0,sizeof(c));
	for(int i=1;i<=x;i++){
		c[a[i].first]+=d[i];
		c[a[i].second+1]-=d[i];
	}
	for(int i=1;i<=n;i++){
		c[i]+=c[i-1];
		if(c[i]>r[i])return 0;
	}
	return 1;
}

